  const h3 = Array.from(document.querySelectorAll('h3')).find(el => el.textContent?.includes('The Phantom of the Opera'));
  if (!h3) return "h3 not found";
  let cur = h3;
  const hierarchy = [];
  for (let i = 0; i < 6 && cur; i++) {
    hierarchy.push({
      tag: cur.tagName,
      className: cur.className,
      hasClick: typeof cur.onclick === 'function',
      role: cur.getAttribute('role'),
      tabIndex: cur.getAttribute('tabindex'),
      href: cur.getAttribute('href'),
      rect: cur.getBoundingClientRect()
    });
    cur = cur.parentElement;
  }
  return {
    h3Text: h3.textContent,
    hierarchy,
    surroundingLinks: Array.from(cur?.querySelectorAll('a') || []).map(a => ({ href: a.href, text: a.textContent }))
  };
});
