const tabId = 1962625065;
const eventDetails = await browserjs(tabId, () => {
  const title = document.title;
  const h1 = document.querySelector('h1')?.textContent?.trim();
  const subheadings = Array.from(document.querySelectorAll('h2, h3, p, span, div')).map(el => el.textContent?.trim()).filter(Boolean);

  // Find date, time, venue
  const dateTimeVenue = Array.from(document.querySelectorAll('[class*="event"], [class*="venue"], [class*="date"], [class*="header"]'))
    .map(el => el.textContent?.trim())
    .filter(t => t && (t.includes('2026') || t.includes('Reynolds') || t.includes('Smith Center') || t.includes('Las Vegas')));

  return {
    url: window.location.href,
    title,
    h1,
    matches: dateTimeVenue.slice(0, 10)
  };
});
console.log("Event details:", JSON.stringify(eventDetails, null, 2));

